    def parse_version(version):
        # Split build metadata
        if '+' in version:
            version, build = version.split('+', 1)
        else:
            build = ''

        # Split pre-release
        if '-' in version:
            base, prerelease = version.split('-', 1)
        else:
            base = version
            prerelease = None

        # Parse base version
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease is not None:
            prerelease_parts = prerelease.split('.')
        else:
            prerelease_parts = None

        return (major, minor, patch, prerelease_parts)

    def compare_prerelease(pre1, pre2):
        # If both are None, they're equal
        if pre1 is None and pre2 is None:
            return 0
        # Version with prerelease sorts before version without
        if pre1 is None:
            return 1
        if pre2 is None:
            return -1

        # Compare pre-release identifiers
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            is_digit1 = id1.isdigit()
            is_digit2 = id2.isdigit()

            if is_digit1 and is_digit2:
                # Both numeric
                num1 = int(id1)
                num2 = int(id2)
                if num1 != num2:
                    return -1 if num1 < num2 else 1
            elif is_digit1:
                # Numeric sorts before non-numeric
                return -1
            elif is_digit2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric, compare lexically
                if id1 != id2:
                    return -1 if id1 < id2 else 1

        # All shared identifiers are equal, fewer sorts first
        if len(pre1) != len(pre2):
            return -1 if len(pre1) < len(pre2) else 1

        return 0

    def sort_key(version):
        parsed = parse_version(version)
        major, minor, patch, prerelease_parts = parsed

        # Create a key for sorting
        # For prerelease: None means no prerelease (sorts after), so use (1,) for no prerelease
        # and (0, prerelease_tuple) for with prerelease
        if prerelease_parts is None:
            prerelease_key = (1,)
        else:
            # Convert each identifier to a comparable form
            prerelease_key = (0,) + tuple(
                (0, int(part)) if part.isdigit() else (1, part)
                for part in prerelease_parts
            )

        return (major, minor, patch, prerelease_key)

    return sorted(versions, key=sort_key)

